SELECT  FROM import_task
 WHERE book_id=#{bookId,jdbcType=BINARY,typeHandler=com.readict.shared.persistence.typehandler.UuidBinaryTypeHandler}
 ORDER BY created_at DESC LIMIT 1

SELECT COUNT(*) FROM import_task
 WHERE user_id=#{userId,jdbcType=BINARY,typeHandler=com.readict.shared.persistence.typehandler.UuidBinaryTypeHandler}
   AND state IN ('QUEUED','RUNNING')

mapper.update:
UPDATE import_task SET lease_until=#{until,jdbcType=TIMESTAMP,typeHandler=com.readict.shared.persistence.typehandler.UtcInstantTypeHandler},
       updated_at=#{now,jdbcType=TIMESTAMP,typeHandler=com.readict.shared.persistence.typehandler.UtcInstantTypeHandler}
 WHERE id=#{id,jdbcType=BINARY,typeHandler=com.readict.shared.persistence.typehandler.UuidBinaryTypeHandler}
   AND lease_token=#{token,jdbcType=BINARY,typeHandler=com.readict.shared.persistence.typehandler.UuidBinaryTypeHandler}
   AND state='RUNNING'
   AND lease_until > #{now,jdbcType=TIMESTAMP,typeHandler=com.readict.shared.persistence.typehandler.UtcInstantTypeHandler}

UPDATE import_task SET stage=#{stage}, updated_at=#{now,jdbcType=TIMESTAMP,typeHandler=com.readict.shared.persistence.typehandler.UtcInstantTypeHandler}
 WHERE id=#{id,jdbcType=BINARY,typeHandler=com.readict.shared.persistence.typehandler.UuidBinaryTypeHandler}
   AND lease_token=#{token,jdbcType=BINARY,typeHandler=com.readict.shared.persistence.typehandler.UuidBinaryTypeHandler}
   AND state='RUNNING'
   AND lease_until > #{now,jdbcType=TIMESTAMP,typeHandler=com.readict.shared.persistence.typehandler.UtcInstantTypeHandler}

UPDATE import_task SET state='SUCCEEDED', lease_token=NULL, lease_until=NULL,
       error_code=NULL, safe_error_message=NULL,
       updated_at=#{now,jdbcType=TIMESTAMP,typeHandler=com.readict.shared.persistence.typehandler.UtcInstantTypeHandler}
 WHERE id=#{id,jdbcType=BINARY,typeHandler=com.readict.shared.persistence.typehandler.UuidBinaryTypeHandler}
   AND lease_token=#{token,jdbcType=BINARY,typeHandler=com.readict.shared.persistence.typehandler.UuidBinaryTypeHandler}
   AND state='RUNNING'
   AND lease_until > #{now,jdbcType=TIMESTAMP,typeHandler=com.readict.shared.persistence.typehandler.UtcInstantTypeHandler}

UPDATE import_task SET state='FAILED', error_code=#{code}, safe_error_message=#{message},
       lease_token=NULL, lease_until=NULL,
       updated_at=#{now,jdbcType=TIMESTAMP,typeHandler=com.readict.shared.persistence.typehandler.UtcInstantTypeHandler}
 WHERE id=#{id,jdbcType=BINARY,typeHandler=com.readict.shared.persistence.typehandler.UuidBinaryTypeHandler}
   AND lease_token=#{token,jdbcType=BINARY,typeHandler=com.readict.shared.persistence.typehandler.UuidBinaryTypeHandler}
   AND state='RUNNING'

UPDATE import_task SET state='FAILED', error_code=#{code}, safe_error_message=#{message},
       updated_at=#{now,jdbcType=TIMESTAMP,typeHandler=com.readict.shared.persistence.typehandler.UtcInstantTypeHandler}
 WHERE id=#{id,jdbcType=BINARY,typeHandler=com.readict.shared.persistence.typehandler.UuidBinaryTypeHandler}
   AND state='QUEUED'

UPDATE import_task SET state='QUEUED', stage='VALIDATING', lease_token=NULL, lease_until=NULL,
       next_attempt_at=#{nextAt,jdbcType=TIMESTAMP,typeHandler=com.readict.shared.persistence.typehandler.UtcInstantTypeHandler},
       error_code=NULL, safe_error_message=NULL,
       updated_at=#{now,jdbcType=TIMESTAMP,typeHandler=com.readict.shared.persistence.typehandler.UtcInstantTypeHandler}
 WHERE id=#{id,jdbcType=BINARY,typeHandler=com.readict.shared.persistence.typehandler.UuidBinaryTypeHandler}
   AND lease_token=#{token,jdbcType=BINARY,typeHandler=com.readict.shared.persistence.typehandler.UuidBinaryTypeHandler}
   AND state='RUNNING'

UPDATE import_task SET state='QUEUED', stage='VALIDATING', lease_token=NULL, lease_until=NULL,
       next_attempt_at=#{nextAt,jdbcType=TIMESTAMP,typeHandler=com.readict.shared.persistence.typehandler.UtcInstantTypeHandler},
       error_code=NULL, safe_error_message=NULL,
       updated_at=#{now,jdbcType=TIMESTAMP,typeHandler=com.readict.shared.persistence.typehandler.UtcInstantTypeHandler}
 WHERE state='RUNNING'
   AND lease_until < #{now,jdbcType=TIMESTAMP,typeHandler=com.readict.shared.persistence.typehandler.UtcInstantTypeHandler}
   AND attempt < #{maxAttempts}

UPDATE import_task SET state='FAILED', error_code='INTERNAL_ERROR', safe_error_message='导入执行超时，已停止',
       lease_token=NULL, lease_until=NULL,
       updated_at=#{now,jdbcType=TIMESTAMP,typeHandler=com.readict.shared.persistence.typehandler.UtcInstantTypeHandler}
 WHERE state='RUNNING'
   AND lease_until < #{now,jdbcType=TIMESTAMP,typeHandler=com.readict.shared.persistence.typehandler.UtcInstantTypeHandler}
   AND attempt >= 3
